mapper.select:
SELECT T1.PFLSH, T2.CUSTOMER_NAME customerName, T1.CUSTOMER_ID, T2.INSITITUTE_CODE insitituteCode, T3.TERM || decode(T3.term_unit,'D','天','W','周','M','月','Y','年','年') as termStr, T3.credit_type as amountType, T1.Mdate, T1.Credit_Amt, T1.UPDATE_TIME FROM credit_lines T1 left join (select T.CUSTOMER_ID, INFO.CUSTOMER_NAME, T.INSITITUTE_CODE from MST_CUSTOMER_INFO_ADD t left join MST_CUSTOMER_INFO info on t.customer_id = info.customer_id where 1 = 1) T2 on T2.CUSTOMER_ID = T1.CUSTOMER_ID left join (select info.credit_mst_id, tag.credit_type, info.term, info.term_unit, dict1.item_value termUnit from credit_conf_info info left join credit_tag_info tag on info.credit_tag_id = tag.credit_tag_id left join sys_datadict_list dict1 on dict1.dict_code = 'TERM_UNIT' and info.TERM_UNIT = dict1.item_code) T3 on T3.credit_mst_id = T1.credit_mst_id where 1 = 1 and T1.Credit_Amt != 0
and T1.pflsh = #{pflsh, jdbcType=VARCHAR}
and T2.CUSTOMER_NAME LIKE CONCAT(CONCAT('%',#{customerName, jdbcType=VARCHAR}),'%')
and TO_CHAR(T1.UPDATE_TIME,'yyyy-MM-dd') >= #{startUpdateTime}
AND TO_CHAR(T1.UPDATE_TIME,'yyyy-MM-dd') <= #{endUpdateTime}
and ( T1.pflsh like 'TY%' or T1.pflsh like 'QY%' or T1.pflsh like 'ABS%') order by T1.UPDATE_TIME

select conf.credit_mst_id
  from credit_conf_info conf
 where 1 = 1
   and conf.credit_tag_id = #{tagId, jdbcType=VARCHAR}
   and conf.term = #{term, jdbcType=DECIMAL}
   and conf.term_unit = #{termUnit, jdbcType=VARCHAR}

select t.CUSTOMER_ID from MST_CUSTOMER_INFO_ADD t where substr(t.insititute_code,9,9) = #{insitituteCode,jdbcType=VARCHAR}

union 

select t.CUSTOMER_ID from MST_CUSTOMER_INFO_ADD t where t.insititute_code = substr(#{insitituteCode,jdbcType=VARCHAR},9,9)

union 

select t.CUSTOMER_ID from MST_CUSTOMER_INFO_ADD t where t.insititute_code = #{insitituteCode,jdbcType=VARCHAR}
